update public.units
set cultural_note = 'Дастархан — the laden Kazakh table — is the centre of hospitality. A guest (қонақ) is sacred. Bread (нан) is never placed face-down, never thrown away, never stepped over. Tea (шай) is offered to every guest, often poured into half-full bowls so the host can refresh it again and again — a sign of attentive welcome. The host gives бата (a short blessing) before and after meals.'
where id = 'u12';

insert into public.vocab (id, unit_id, native, english) values
